mapper.select:
SELECT COUNT(*)
FROM MEMBER
WHERE LOGIN_ID = #{loginId}

SELECT COUNT(*)
FROM MEMBER
WHERE NICKNAME = #{nickname}

SELECT COUNT(*)
FROM MEMBER
WHERE LOGIN_ID = #{id}
AND PASSWORD = #{password}
AND MEMBER_STATUS = 'ACTIVE'

SELECT ROLE
FROM MEMBER
WHERE LOGIN_ID = #{loginId}

SELECT COUNT(*)
FROM MEMBER
WHERE LOGIN_ID = #{loginId}
  AND NAME = #{name}
  AND REPLACE(PHONE, '-', '') = REPLACE(#{phone}, '-', '')
  AND MEMBER_STATUS = 'ACTIVE'

mapper.update:
UPDATE MEMBER
SET PASSWORD = #{password}
WHERE LOGIN_ID = #{loginId}
  AND NAME = #{name}
  AND REPLACE(PHONE, '-', '') = REPLACE(#{phone}, '-', '')
  AND MEMBER_STATUS = 'ACTIVE'
